  </style>
</head>
<body>
  <div class="container">
    <header>
      <h1>Autonomous Maze Exploration</h1>
    </header>

    <div class="dashboard">
      <div class="stat-box">
        <span class="stat-label">Completed</span>
        <span class="stat-value" id="completed">0 / 24</span>
      </div>
      <div class="stat-box">
        <span class="stat-label">Elapsed Ticks</span>
        <span class="stat-value" id="timer">0</span>
      </div>
      <div class="controls">
        <button id="playBtn" class="secondary">Pause</button>
        <button id="stepBtn" class="secondary">Step</button>
        <button id="reset">Reset</button>
      </div>
    </div>

    <div id="maze">
      <canvas id="mazeCanvas" width="510" height="510"></canvas>
    </div>

    <div class="legend">
      <div class="legend-item"><div class="legend-dot" style="background:#10b981;"></div> Spawn (0,0)</div>
      <div class="legend-item"><div class="legend-dot" style="background:#f59e0b;"></div> Exit (16,16)</div>
      <div class="legend-item"><div class="legend-dot" style="background:#ef4444;"></div> Dead-End Pruned</div>
      <div class="legend-item"><div class="legend-dot" style="background:#38bdf8;"></div> 24 Trémaux DFS Bots</div>
    </div>
  </div>

  <script>
    (function() {
      const ROWS = 17;
      const COLS = 17;
      const CELL_SIZE = 30; // 17 * 30 = 510px
      const CANVAS_SIZE = ROWS * CELL_SIZE;

      const canvas = document.getElementById('mazeCanvas');
      const ctx = canvas.getContext('2d');
      const completedEl = document.getElementById('completed');
      const timerEl = document.getElementById('timer');
      const resetBtn = document.getElementById('reset');
      const playBtn = document.getElementById('playBtn');
      const stepBtn = document.getElementById('stepBtn');

      canvas.width = CANVAS_SIZE;
      canvas.height = CANVAS_SIZE;

      // PRNG (Mulberry32)
      function createRNG(seed) {
        let s = (seed >>> 0) || 1337;
        return function() {
          let t = s += 0x6D2B79F5;
          t = Math.imul(t ^ (t >>> 15), t | 1);
          t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
          return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
        };
      }

      // Generate all 24 permutations of directions for 24 distinct bot preferences
      function getPermutations(arr) {
        if (arr.length <= 1) return [arr];
        const res = [];
        for (let i = 0; i < arr.length; i++) {
          const cur = arr[i];
          const rem = arr.slice(0, i).concat(arr.slice(i + 1));
          for (const p of getPermutations(rem)) {
            res.push([cur, ...p]);
          }
        }
        return res;
      }
      const ALL_PREFS = getPermutations(['n', 'e', 's', 'w']);

      const DIR_DELTA = {
        n: { r: -1, c: 0, opp: 's' },
        e: { r: 0, c: 1, opp: 'w' },
        s: { r: 1, c: 0, opp: 'n' },
        w: { r: 0, c: -1, opp: 'e' }
      };

      // 24 distinct vibrant colors
      const BOT_COLORS = Array.from({ length: 24 }, (_, i) => `hsl(${Math.round(i * 360 / 24)}, 85%, 60%)`);

      // Maze & Game state
      let rng;
      let grid = []; // 2D array of {n, e, s, w}
      let bots = [];
      let isRunning = true;
      let animProgress = 1.0;
      let lastFrameTime = performance.now();
      const TICKS_PER_SEC = 12;

      // Public game object
      window.game = {
        size: { rows: ROWS, cols: COLS },
        spawn: { r: 0, c: 0 },
        exit: { r: ROWS - 1, c: COLS - 1 },
        elapsed: 0,
        bots: [],
        walls: function(r, c) {
          if (r < 0 || r >= ROWS || c < 0 || c >= COLS) {
            return { n: true, e: true, s: true, w: true };
          }
          return {
            n: grid[r][c].n,
            e: grid[r][c].e,
            s: grid[r][c].s,
            w: grid[r][c].w
          };
        },
        tick: function(n = 1) {
          for (let i = 0; i < n; i++) {
            stepSimulation();
          }
          animProgress = 1.0;
          updateUI();
          render();
        },
        reset: function(seed) {
          init(seed);
        }
      };

      function generateMaze(rngFn) {
        const g = Array.from({ length: ROWS }, () =>
          Array.from({ length: COLS }, () => ({ n: true, e: true, s: true, w: true, visited: false }))
        );

        const stack = [{ r: 0, c: 0 }];
        g[0][0].visited = true;

        const dirs = ['n', 'e', 's', 'w'];

        while (stack.length > 0) {
          const cur = stack[stack.length - 1];
          const unvisitedNeighbors = [];

          for (const d of dirs) {
            const nr = cur.r + DIR_DELTA[d].r;
            const nc = cur.c + DIR_DELTA[d].c;
            if (nr >= 0 && nr < ROWS && nc >= 0 && nc < COLS && !g[nr][nc].visited) {
              unvisitedNeighbors.push({ dir: d, r: nr, c: nc });
            }
          }

          if (unvisitedNeighbors.length > 0) {
            const idx = Math.floor(rngFn() * unvisitedNeighbors.length);
            const chosen = unvisitedNeighbors[idx];
            g[cur.r][cur.c][chosen.dir] = false;
            g[chosen.r][chosen.c][DIR_DELTA[chosen.dir].opp] = false;
            g[chosen.r][chosen.c].visited = true;
            stack.push({ r: chosen.r, c: chosen.c });
          } else {
            stack.pop();
          }
        }

        return g;
      }

      function createBots() {
        return Array.from({ length: 24 }, (_, i) => {
          const spawnPos = { r: window.game.spawn.r, c: window.game.spawn.c };
          const bot = {
            id: i,
            color: BOT_COLORS[i],
            pref: ALL_PREFS[i],
            path: [{ r: spawnPos.r, c: spawnPos.c }],
            deadEnds: [],
            finishTick: null,
            // Internal navigation state
            current: { ...spawnPos },
            prevPos: { ...spawnPos },
            stack: [],
            visitedSet: new Set([`${spawnPos.r},${spawnPos.c}`]),
            deadSet: new Set()
          };
          return bot;
        });
      }

      function stepBot(bot, tickNum) {
        if (bot.finishTick !== null) return;

        bot.prevPos = { ...bot.current };
        const curr = bot.current;
        const walls = window.game.walls(curr.r, curr.c);

        let chosenDir = null;
        let nextCell = null;

        for (const dir of bot.pref) {
          if (walls[dir]) continue; // wall blocking
          const nr = curr.r + DIR_DELTA[dir].r;
          const nc = curr.c + DIR_DELTA[dir].c;
          const key = `${nr},${nc}`;
          if (!bot.visitedSet.has(key) && !bot.deadSet.has(key)) {
            chosenDir = dir;
            nextCell = { r: nr, c: nc };
            break;
          }
        }

        if (nextCell) {
          // Advance forward along unvisited branch
          bot.stack.push({ r: curr.r, c: curr.c });
          bot.visitedSet.add(`${nextCell.r},${nextCell.c}`);
          bot.current = nextCell;
          bot.path.push({ r: nextCell.r, c: nextCell.c });

          if (nextCell.r === window.game.exit.r && nextCell.c === window.game.exit.c) {
            bot.finishTick = tickNum;
          }
        } else {
          // Dead end or fully explored branch -> backtrack & mark dead
          bot.deadSet.add(`${curr.r},${curr.c}`);
          bot.deadEnds.push({ r: curr.r, c: curr.c });

          if (bot.stack.length > 0) {
            const prev = bot.stack.pop();
            bot.current = prev;
            bot.path.push({ r: prev.r, c: prev.c });

            if (prev.r === window.game.exit.r && prev.c === window.game.exit.c) {
              bot.finishTick = tickNum;
            }
          }
        }
      }

      function stepSimulation() {
        const allDone = bots.every(b => b.finishTick !== null);
        if (allDone) return;

        window.game.elapsed++;
        const currentTick = window.game.elapsed;

        for (let i = 0; i < bots.length; i++) {
          if (bots[i].finishTick === null) {
            stepBot(bots[i], currentTick);
          }
        }
      }

      function init(seed) {
        const numericSeed = (typeof seed === 'number') ? seed : Math.floor(Math.random() * 10000000);
        rng = createRNG(numericSeed);
        grid = generateMaze(rng);
        bots = createBots();
        window.game.bots = bots;
        window.game.elapsed = 0;
        animProgress = 1.0;
        lastFrameTime = performance.now();
        updateUI();
        render();
      }

      function updateUI() {
        const completedCount = bots.filter(b => b.finishTick !== null).length;
        completedEl.innerText = `${completedCount} / 24`;
        timerEl.innerText = `${window.game.elapsed}`;
      }

      function render() {
        ctx.clearRect(0, 0, CANVAS_SIZE, CANVAS_SIZE);

        // Fill background corridors
        ctx.fillStyle = '#0f172a';
        ctx.fillRect(0, 0, CANVAS_SIZE, CANVAS_SIZE);

        // Draw Spawn & Exit Highlights
        const spawnX = window.game.spawn.c * CELL_SIZE;
        const spawnY = window.game.spawn.r * CELL_SIZE;
        ctx.fillStyle = 'rgba(16, 185, 129, 0.25)';
        ctx.fillRect(spawnX, spawnY, CELL_SIZE, CELL_SIZE);

        const exitX = window.game.exit.c * CELL_SIZE;
        const exitY = window.game.exit.r * CELL_SIZE;
        ctx.fillStyle = 'rgba(245, 158, 11, 0.35)';
        ctx.fillRect(exitX, exitY, CELL_SIZE, CELL_SIZE);

        // Spawn / Exit icons
        ctx.fillStyle = '#10b981';
        ctx.beginPath();
        ctx.arc(spawnX + CELL_SIZE / 2, spawnY + CELL_SIZE / 2, 4, 0, Math.PI * 2);
        ctx.fill();

        ctx.fillStyle = '#f59e0b';
        ctx.beginPath();
        ctx.arc(exitX + CELL_SIZE / 2, exitY + CELL_SIZE / 2, 6, 0, Math.PI * 2);
        ctx.fill();

        // Draw Maze Walls
        ctx.strokeStyle = '#64748b';
        ctx.lineWidth = 2;
        ctx.lineCap = 'square';
        ctx.beginPath();

        for (let r = 0; r < ROWS; r++) {
          for (let c = 0; c < COLS; c++) {
            const x = c * CELL_SIZE;
            const y = r * CELL_SIZE;
            const cell = grid[r][c];

            if (cell.n) {
              ctx.moveTo(x, y);
              ctx.lineTo(x + CELL_SIZE, y);
            }
            if (cell.w) {
              ctx.moveTo(x, y);
              ctx.lineTo(x, y + CELL_SIZE);
            }
            if (cell.e && c === COLS - 1) {
              ctx.moveTo(x + CELL_SIZE, y);
              ctx.lineTo(x + CELL_SIZE, y + CELL_SIZE);
            }
            if (cell.s && r === ROWS - 1) {
              ctx.moveTo(x, y + CELL_SIZE);
              ctx.lineTo(x + CELL_SIZE, y + CELL_SIZE);
            }
          }
        }
        ctx.stroke();

        // Draw Bots smoothly
        const t = Math.min(1.0, Math.max(0.0, animProgress));
        // Group bots slightly to offset overlap
        for (let i = 0; i < bots.length; i++) {
          const bot = bots[i];
          const cur = bot.current;
          const prev = bot.prevPos || cur;

          const cx = (prev.c + (cur.c - prev.c) * t + 0.5) * CELL_SIZE;
          const cy = (prev.r + (cur.r - prev.r) * t + 0.5) * CELL_SIZE;

          // Slight radial jitter per bot so they don't completely occlude one another
          const angle = (i / 24) * Math.PI * 2;
          const jitter = bot.finishTick !== null ? 0 : 3.5;
          const bx = cx + Math.cos(angle) * jitter;
          const by = cy + Math.sin(angle) * jitter;

          ctx.fillStyle = bot.color;
          ctx.beginPath();
          ctx.arc(bx, by, bot.finishTick !== null ? 3.5 : 4.5, 0, Math.PI * 2);
          ctx.fill();
          ctx.strokeStyle = '#090d16';
          ctx.lineWidth = 1;
          ctx.stroke();
        }
      }

      // Main animation loop
      function loop(now) {
        const dt = (now - lastFrameTime) / 1000;
        lastFrameTime = now;

        const allDone = bots.every(b => b.finishTick !== null);

        if (isRunning && !allDone) {
          animProgress += dt * TICKS_PER_SEC;
          while (animProgress >= 1.0) {
            animProgress -= 1.0;
            stepSimulation();
            updateUI();
          }
        } else {
          animProgress = 1.0;
        }

        render();
        requestAnimationFrame(loop);
      }

      // Event Listeners
      resetBtn.addEventListener('click', () => {
        init();
      });

      playBtn.addEventListener('click', () => {
        isRunning = !isRunning;
        playBtn.innerText = isRunning ? 'Pause' : 'Play';
      });

      stepBtn.addEventListener('click', () => {
        isRunning = false;
        playBtn.innerText = 'Play';
        window.game.tick(1);
      });

      // Initialize on load
      init();
      requestAnimationFrame(loop);
    })();
  </script>
</body>
</html>
